/// Returns the output views your team can use: views DigitalOcean publishes to every team, plus your team's own. Cursor-paged with `page_size` and `page_token`; no total is reported.
///
/// [tool] At most one of tool or `tool_id`, as on create. With one set, the
///   list is the published views plus your team's own on that tool version. With
///   neither, it is every live view your team owns plus every published view on a
///   tool version your catalog exposes, across tools.
/// [toolId] Opaque ID of the tool version; see tool.
/// [pageSize] Page size, 1 to 100. Defaults to 20 when omitted or 0; other
///   values are rejected with 400.
/// [pageToken] `next_page_token` from the previous response. Valid only with
///   the same tool selection; otherwise the request is rejected with 400.
Stream<OutputView> outputViewsListPaginated(ClientConfig config,
    {String? tool,
    String? toolId,
    int? pageSize,
    String? pageToken,
    RequestOptions? requestOptions}) async* {
  var sdkCursor = pageToken;
  while (true) {
    final sdkPage = await outputViewsList(config,
        tool: tool == null
            ? const SdkOmitted<String>()
            : SdkPresent<String>(tool),
        toolId: toolId == null
            ? const SdkOmitted<String>()
            : SdkPresent<String>(toolId),
        pageSize: pageSize == null
            ? const SdkOmitted<int>()
            : SdkPresent<int>(pageSize),
        pageToken: sdkCursor == null
            ? const SdkOmitted<String>()
            : SdkPresent<String>(sdkCursor),
        requestOptions: requestOptions);
    final sdkItems = sdkPage.views.valueOrNull ?? [];
    if (sdkItems.isEmpty) return;
    for (final sdkItem in sdkItems) {
      yield sdkItem;
    }
    final sdkNext = sdkPage.nextPageToken.valueOrNull;
    if (sdkNext == null) return;
    sdkCursor = sdkNext;
  }
}

Stream<SdkPage<ListOutputViewsResponse, OutputView>> outputViewsListPages(
    ClientConfig config,
    {String? tool,
    String? toolId,
    int? pageSize,
    String? pageToken,
    RequestOptions? requestOptions}) async* {
  var sdkCursor = pageToken;
  while (true) {
    final sdkPage = await outputViewsList(config,
        tool: tool == null
            ? const SdkOmitted<String>()
            : SdkPresent<String>(tool),
        toolId: toolId == null
            ? const SdkOmitted<String>()
            : SdkPresent<String>(toolId),
        pageSize: pageSize == null
            ? const SdkOmitted<int>()
            : SdkPresent<int>(pageSize),
        pageToken: sdkCursor == null
            ? const SdkOmitted<String>()
            : SdkPresent<String>(sdkCursor),
        requestOptions: requestOptions);
    final sdkItems = sdkPage.views.valueOrNull ?? [];
    if (sdkItems.isEmpty) return;
    final sdkNext = sdkPage.nextPageToken.valueOrNull;
    final sdkHasMore = sdkNext != null;
    yield SdkPage(data: sdkPage, items: sdkItems, hasMore: sdkHasMore);
    if (!sdkHasMore) return;
    sdkCursor = sdkNext;
  }
}

